// In frontend/src/DataChart.js

import React, { useState, useEffect, useRef } from 'react';
import { Line } from 'react-chartjs-2';
import {
  Chart as ChartJS, CategoryScale, LinearScale, PointElement,
  LineElement, Title, Tooltip, Legend
} from 'chart.js';
// We no longer need the time scale or the date adapter
import { generateColorGradient } from './colorUtils';

ChartJS.register(CategoryScale, LinearScale, PointElement, LineElement, Title, Tooltip, Legend);

// --- NEW: User-specified color palette ---
const pidColors = [
    { main: '#00fffa', dark: '#005554' }, // Cyan
    { main: '#0036ff', dark: '#001255' }, // Blue
    { main: '#f000ff', dark: '#500055' }, // Magenta
    { main: '#ff5300', dark: '#551c00' }, // Orange
    { main: '#ffe600', dark: '#554d00' }, // Yellow
    { main: '#a2ff00', dark: '#365500' }, // Green
];

const DataChart = ({ groupData, onTimeRangeChange }) => {
    const chartRef = useRef(null);
    const [zoom, setZoom] = useState(10); // Still in minutes
    const [selectedPids, setSelectedPids] = useState({
        pid1: 'Engine RPM',
        pid2: 'None',
        pid3: 'None',
    });

    // --- REWRITTEN: Process data to use ELAPSED TIME ---
    const datasets = Object.entries(selectedPids)
        .filter(([, pidName]) => pidName && pidName !== 'None')
        .flatMap(([pidKey, pidName], pidIndex) => {
            const numLogs = groupData.logs.length;
            const colorSet = pidColors[pidIndex % pidColors.length]; // Use the new color sets
            const colors = generateColorGradient(colorSet.main, colorSet.dark, numLogs);

            return groupData.logs.map((log, logIndex) => {
                const logId = log.log_id;
                const logData = groupData.all_data[logId] || [];
                const logColumns = groupData.all_columns[logId] || [];
                // Find the sanitized column name that corresponds to the selected PID name
                const pidSanitized = Object.keys(groupData.all_columns[logId]).find(key => 
                    groupData.all_columns[logId][key].toLowerCase().replace(/[\s\W]/g, '_') === pidName.toLowerCase().replace(/[\s\W]/g, '_')
                );

                if (logData.length === 0 || !pidSanitized) {
                    return null; // Return null for logs that don't have this PID
                }

                const startTime = logData[0].timestamp; // Get the start time for THIS log
                const data = logData.map(d => ({
                    // X is now elapsed seconds from the start of this specific log
                    x: (d.timestamp - startTime) / 1000, 
                    y: d[pidSanitized]
                }));

                return {
                    label: `${log.file_name} - ${pidName}`,
                    data: data,
                    borderColor: colors[logIndex],
                    backgroundColor: colors[logIndex],
                    yAxisID: `y${pidIndex + 1}`,
                    tension: 0.2,
                    pointRadius: 0,
                    borderWidth: 2,
                };
            }).filter(Boolean); // Filter out any null datasets
        });

    const handlePidChange = (pidKey, value) => {
        setSelectedPids(prev => ({ ...prev, [pidKey]: value }));
    };

    const handleZoomChange = (newZoomInMinutes) => {
        setZoom(newZoomInMinutes);
        const chart = chartRef.current;
        if (!chart) return;

        const newMax = newZoomInMinutes * 60; // Convert minutes to seconds
        chart.options.scales.x.min = 0;
        chart.options.scales.x.max = newMax;
        chart.update();
        onTimeRangeChange({ min: 0, max: newMax });
    };

    const options = {
        responsive: true,
        maintainAspectRatio: false,
        interaction: { mode: 'index', intersect: false },
        plugins: {
            title: { display: true, text: 'Trip Group Log Comparison' },
        },
        scales: {
            // --- UPDATED: X-axis is now a linear scale for seconds ---
            x: {
                type: 'linear',
                title: { display: true, text: 'Elapsed Time (seconds)' },
            },
            y1: {
                type: 'linear',
                display: selectedPids.pid1 !== 'None',
                position: 'left',
                title: { display: true, text: selectedPids.pid1, font: { size: 14 }, color: pidColors[0].main },
                ticks: { color: pidColors[0].main },
            },
            y2: {
                type: 'linear',
                display: selectedPids.pid2 !== 'None',
                position: 'left',
                grid: { drawOnChartArea: false },
                title: { display: true, text: selectedPids.pid2, font: { size: 14 }, color: pidColors[2].main },
                ticks: { color: pidColors[2].main },
            },
            y3: {
                type: 'linear',
                display: selectedPids.pid3 !== 'None',
                position: 'right',
                grid: { drawOnChartArea: false },
                title: { display: true, text: selectedPids.pid3, font: { size: 14 }, color: pidColors[4].main },
                ticks: { color: pidColors[4].main },
            },
        },
    };

    useEffect(() => {
        if (groupData) handleZoomChange(10); // Set initial 10-minute (600 second) view
    }, [groupData]);

    const pidSelector = (pidKey, colorIndex) => (
        <select value={selectedPids[pidKey]} onChange={(e) => handlePidChange(pidKey, e.target.value)} style={{ borderColor: pidColors[colorIndex].main, color: pidColors[colorIndex].main, marginRight: '10px' }}>
            <option>None</option>
            {groupData.combined_pids.map(pid => <option key={pid} value={pid}>{pid}</option>)}
        </select>
    );

    return (
        <div>
            <div className="controls" style={{ padding: '10px', display: 'flex', justifyContent: 'space-between' }}>
                <div>
                    {pidSelector('pid1', 0)}
                    {pidSelector('pid2', 2)}
                    {pidSelector('pid3', 4)}
                </div>
                <div>
                    <span>Zoom: </span>
                    <button onClick={() => handleZoomChange(2)}>2m</button>
                    <button onClick={() => handleZoomChange(5)}>5m</button>
                    <button onClick={() => handleZoomChange(10)}>10m</button>
                </div>
            </div>
            <div style={{ height: '480px' }}>
                <Line ref={chartRef} options={options} data={{ datasets }} />
            </div>
        </div>
    );
};

export default DataChart;
